"""Position windows over trades."""


def volume_between(trades, low, high):
    """Return the volume of the trades at positions low to high, both included. Positions start at 1."""
    return [x.volume for x in trades[low - 1:high - 1]]


def first_volumes(trades, n):
    """Return the volume of the first n trades."""
    return volume_between(trades, 1, n)

